mapper.select:
SELECT *
FROM eb_store_coupon_user
where
`status` = 0
AND min_price <= #{maxPrice}
AND start_time < #{date} AND end_time > #{date}
AND uid = #{uid}
AND (use_type = 1
         or (use_type = 2 and

    find_in_set(#{proId}, primary_key)

         )
         or (use_type = 3 and

    find_in_set(#{cateId}, primary_key)

         )
    )
order by id desc

SELECT scu.*
FROM eb_store_coupon_user AS scu
left join eb_user as u on scu.uid = u.uid


        and scu.name = #{name}


        and scu.coupon_id = #{couponId}


        and scu.status = #{status}


        and (
        scu.uid like CONCAT('%',#{keywords},'%') or
        u.nickname like CONCAT('%',#{keywords},'%') or
        u.phone like CONCAT('%',#{keywords},'%')
        )


        and scu.uid = #{uid}


        and u.nickname like CONCAT('%',#{nickname},'%')


        and u.phone like CONCAT('%',#{phone},'%')


order by scu.id desc
